package com.weaponsregistration.reservation.controller;import com.weaponsregistration.reservation.dto.ReservationContract.*;import com.weaponsregistration.reservation.service.ReservationService;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/erp/reservations")public class ReservationController{private final ReservationService service;public ReservationController(ReservationService service){this.service=service;}@GetMapping("/stock")public Page<StockOption>stock(@RequestParam long organizationId,@RequestParam(required=false)Long unitId,@RequestParam String kind,@RequestParam(defaultValue="")String search){return service.stock(organizationId,unitId,kind,search);}@PostMapping public ReservationView create(@RequestBody CreateRequest request){return service.create(request);}@PostMapping("/{id}/cancel")public ReservationView cancel(@PathVariable long id){return service.release(id,"CANCELLED");}@PostMapping("/{id}/expire")public ReservationView expire(@PathVariable long id){return service.release(id,"EXPIRED");}@GetMapping public Page<ReservationView>list(@RequestParam long organizationId,@RequestParam(required=false)Long unitId,@RequestParam(defaultValue="0")int page){return service.list(organizationId,unitId,page);}}
